ALTER POLICY sessions_read ON public.academic_sessions TO authenticated USING (public.has_role(auth.uid(), 'super_admin'::public.app_role) OR public.has_role(auth.uid(), 'teacher'::public.app_role) OR public.has_role(auth.uid(), 'student'::public.app_role));
